(async () => {
  const fileBase64 = 'data:application/pdf;base64,' + '';
  console.log('[UI] fetch START');
  const t0 = performance.now();
  const res = await fetch('/api/ai/generate-audio-questions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      pdfBase64: fileBase64,
      fileText: '',
      mcqCount: 3,
      tfCount: 2,
      difficulty: 'Medium'
    })
  });
  console.log('[UI] fetch END');
  console.log('[UI] response status: ' + res.status + ' ' + res.statusText);
  
  // Note: content-length header may not be exposed if not CORS or transfer-encoding is chunked
  console.log('[UI] response content-length: ' + res.headers.get('content-length') + ' | type: ' + res.headers.get('content-type'));
  
  console.log('[UI] res.json START');
  const t1 = performance.now();
  const data = await res.json();
  const t2 = performance.now();
  console.log('[UI] res.json END');
  
  console.log('[UI] fetch duration:', (t1 - t0).toFixed(0), 'ms');
  console.log('[UI] res.json duration:', (t2 - t1).toFixed(0), 'ms');
  
  const responseSizeMB = (JSON.stringify(data).length / (1024*1024)).toFixed(2);
  console.log('[UI] response body size (approx):', responseSizeMB, 'MB');
  
  return 'DONE';
})();
